from pathlib import Path
import html,json,hashlib
root=Path('products/services/software-renewals')
p=root/'supplier-access/preparation/worksheet-en-fr.md'
text=p.read_text()
out=root/'supplier-access/preparation'
out.mkdir(parents=True,exist_ok=True)
page='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Supplier bid-effort worksheet / Fiche fournisseur</title><style>body{max-width:75ch;margin:2rem auto;padding:1rem;font:18px/1.6 system-ui}pre{white-space:pre-wrap;font:inherit;overflow-wrap:anywhere}</style><main><pre>'+html.escape(text)+'</pre></main></html>'
(out/'supplier-access-draft.html').write_text(page)
packet={'status':'DRAFT_NOT_SOURCE_VERIFIED_NOT_DEPLOYED','worksheet_sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'html_sha256':hashlib.sha256(page.encode()).hexdigest(),'source_artifacts':[],'live_baselines':[],'public_files_modified':False,'remaining':['Verify material statements against original official sources','Demonstrate complete isolation from rejected and unrelated candidates','Obtain exact-digest independent review before publication']}
for sub in ['framework-access','gcloud15-access']:
 d=root/sub
 if d.exists():
  for f in sorted(d.rglob('*')):
   if f.is_file(): packet['source_artifacts'].append({'path':str(f),'bytes':f.stat().st_size,'sha256':hashlib.sha256(f.read_bytes()).hexdigest()})
for name in ['live-index.html','live-renewals.html']:
 f=root/'integration/release'/name
 if f.exists(): packet['live_baselines'].append({'path':str(f),'bytes':f.stat().st_size,'sha256':hashlib.sha256(f.read_bytes()).hexdigest()})
(out/'delivery-handoff.json').write_text(json.dumps(packet,ensure_ascii=False,indent=2)+'\n')
print((out/'delivery-handoff.json').read_text())
print('HTML draft saved; no site files modified.')
